INSERT INTO feature VALUES('operations','rules','Operations','presented-types','implemented','notable',NULL,'`oper` declares a term former the rules compute, including operations with several outputs. A call names each output by the label its port is written with, as a function''s call does: it selects one, `divmod(m, n).rem`, binds them by label, `let (.rem = r, .quot = q) = divmod(m, n);`, and stands as the record over them, `let d = divmod(m, n); d.rem`.','surface-lowering theory-computads','corpus/model/desc/many-out-op.gandr corpus/model/desc/desc-op-cells.gandr corpus/model/data/indexed-family-operation.gandr crates/surface-lowering/src/lower/arity/tests.rs::an_operation_s_outputs_are_selected_and_bound_by_label_5147','corpus/model/desc/many-out-op.gandr',NULL);
